def pairs(it):
    """Return a list of consecutive pairs from an iterator."""
    return [list(it)[:2]] + [list(it)[i:i+2] for i in range(1, len(it)-1)]

def chunk(lst, size):
    """Split a list into consecutive chunks of a specified size."""
    return [lst[i:i + size] for i in range(0, len(lst), size)]

import re

def calc(expr):
    pattern = r'^(\d+)\s*([+-])\s*(\d+)$'
    match = re.match(pattern, expr)
    if match:
        num1, op, num2 = map(int, match.groups())
        if op == '+':
            return num1 + num2
        elif op == '-':
            return num1 - num2
